create table permissions (id uuid primary key, version bigint not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, code varchar(80) not null unique, description varchar(255) not null);
create table roles (id uuid primary key, version bigint not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, name varchar(50) not null unique);
create table users (id uuid primary key, version bigint not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, username varchar(80) not null unique, email varchar(160) not null unique, password varchar(255) not null, enabled boolean not null, account_locked boolean not null, last_login_at timestamp(6) with time zone);
create table role_permissions (role_id uuid not null references roles(id), permission_id uuid not null references permissions(id), primary key(role_id, permission_id));
create table user_roles (user_id uuid not null references users(id), role_id uuid not null references roles(id), primary key(user_id, role_id));
create table categories (id uuid primary key, version bigint not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, name varchar(255) not null unique, description varchar(255), active boolean not null);
create table manufacturers (id uuid primary key, version bigint not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, name varchar(255) not null unique, contact_person varchar(255), phone varchar(255), email varchar(255), address varchar(255), gstin varchar(255), active boolean not null);
create table suppliers (id uuid primary key, version bigint not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, supplier_code varchar(255) not null unique, company_name varchar(255) not null, contact_person varchar(255), phone varchar(255), email varchar(255), address varchar(255), gstin varchar(255), payment_terms varchar(255), status varchar(30));
create table medicines (id uuid primary key, version bigint not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, medicine_code varchar(60) not null unique, name varchar(255) not null, generic_name varchar(255), brand_name varchar(255), manufacturer_id uuid references manufacturers(id), category_id uuid references categories(id), composition varchar(255), dosage_form varchar(30), strength varchar(255), pack_size varchar(255), unit varchar(255), prescription_required boolean not null, tax_percentage numeric(5,2), reorder_level numeric(14,3), description text, status varchar(30) not null);
create table employees (id uuid primary key, version bigint not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, employee_code varchar(255) not null unique, first_name varchar(255) not null, last_name varchar(255) not null, phone varchar(255), email varchar(255), address varchar(255), designation varchar(255), joining_date date, salary numeric(38,2), status varchar(30) not null, branch varchar(255), user_id uuid unique references users(id));
create table medicine_batches (id uuid primary key, version bigint not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, medicine_id uuid not null references medicines(id), batch_number varchar(255) not null, manufacturing_date date, expiry_date date not null, purchase_price numeric(14,2) not null, mrp numeric(14,2) not null, selling_price numeric(14,2) not null, quantity numeric(14,3) not null, reserved_quantity numeric(14,3) not null, supplier_id uuid references suppliers(id), constraint uk_batch_medicine unique(medicine_id,batch_number));
create table purchase_orders (id uuid primary key, version bigint not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, purchase_order_number varchar(255) not null unique, supplier_id uuid not null references suppliers(id), order_date date not null, expected_delivery_date date, status varchar(40) not null, subtotal numeric(14,2), discount numeric(14,2), tax numeric(14,2), total_amount numeric(14,2), notes varchar(255), created_by_id uuid references users(id), approved_by_id uuid references users(id));
create table purchase_order_items (id uuid primary key, version bigint not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, purchase_order_id uuid not null references purchase_orders(id), medicine_id uuid not null references medicines(id), quantity numeric(14,3) not null, unit_price numeric(14,2) not null, discount numeric(14,2), tax numeric(14,2), total numeric(14,2) not null);
create table stock_movements (id uuid primary key, version bigint not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, medicine_batch_id uuid not null references medicine_batches(id), movement_type varchar(30) not null, quantity numeric(14,3) not null, previous_quantity numeric(14,3) not null, new_quantity numeric(14,3) not null, reference_type varchar(255), reference_id uuid, reason varchar(255), created_by_id uuid references users(id));
create table audit_logs (id uuid primary key, version bigint not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, user_id uuid references users(id), action varchar(80) not null, entity_type varchar(80) not null, entity_id uuid not null, old_value text, new_value text, ip_address varchar(255));
create index idx_medicine_code on medicines(medicine_code); create index idx_medicine_name on medicines(name); create index idx_medicine_generic on medicines(generic_name); create index idx_supplier_code on suppliers(supplier_code); create index idx_supplier_name on suppliers(company_name); create index idx_employee_code on employees(employee_code); create index idx_employee_email on employees(email); create index idx_batch_expiry on medicine_batches(expiry_date); create index idx_purchase_number on purchase_orders(purchase_order_number); create index idx_purchase_status on purchase_orders(status); create index idx_movement_batch on stock_movements(medicine_batch_id); create index idx_audit_entity on audit_logs(entity_type,entity_id);
